using System;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace Underwater.Editor {
public static class ReefBlenderSquid {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Folder="Assets/UnderwaterArt/BlenderSquid",Model=Folder+"/ReferenceSquid.fbx";
 static Vector3[] Points(SkinnedMeshRenderer skin,Transform root){var mesh=new Mesh();skin.BakeMesh(mesh,false);var points=mesh.vertices;float scale=skin.rootBone.lossyScale.x;for(int i=0;i<points.Length;i++)points[i]=root.InverseTransformPoint(skin.transform.TransformPoint(points[i]/scale));UnityEngine.Object.DestroyImmediate(mesh);return points;}
 static Bounds BoundsOf(SkinnedMeshRenderer skin,Transform root){var points=Points(skin,root);Bounds bounds=new Bounds(points[0],Vector3.zero);foreach(var point in points)bounds.Encapsulate(point);return bounds;}
 static Material Material(string name,string shader,string texture){string path=Folder+"/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find(shader));AssetDatabase.CreateAsset(mat,path);}mat.shader=Shader.Find(shader);mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/"+texture+".png");mat.color=Color.white;EditorUtility.SetDirty(mat);return mat;}
 public static void Run(){Inspect();Apply();Validate();Capture();}
 public static void Apply(){var scene=EditorSceneManager.OpenScene(Scene);var bodyMat=Material("SquidBody","Underwater/Imported Squid Skin","SquidSkin");var finMat=Material("SquidFin","Underwater/Imported Squid Fin","SquidFin");foreach(string texture in new[]{"SquidSkin","SquidFin"}){var importer=(TextureImporter)AssetImporter.GetAtPath(Folder+"/"+texture+".png");importer.mipmapEnabled=true;importer.alphaSource=TextureImporterAlphaSource.FromInput;var settings=importer.GetPlatformTextureSettings("Android");settings.overridden=true;settings.maxTextureSize=1024;settings.format=TextureImporterFormat.ASTC_6x6;importer.SetPlatformTextureSettings(settings);importer.SaveAndReimport();}
  foreach(var squid in UnityEngine.Object.FindObjectsByType<SquidSwimmer>(FindObjectsSortMode.None)){var old=squid.transform.Find("Approved Blender squid");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Model));model.name="Approved Blender squid";model.transform.SetParent(squid.transform,false);var skin=model.GetComponentInChildren<SkinnedMeshRenderer>();var root=Array.Find(skin.bones,b=>b.name=="Root");var mantle=Array.Find(skin.bones,b=>b.name=="Mantle");var axis=model.transform.InverseTransformDirection(mantle.position-root.position);model.transform.localRotation=Quaternion.FromToRotation(axis,Vector3.forward)*model.transform.localRotation;
   var animation=model.GetComponent<Animation>();if(!animation)throw new Exception("Imported squid animation missing");animation.wrapMode=WrapMode.Loop;animation.playAutomatically=true;animation.cullingType=AnimationCullingType.BasedOnRenderers;animation.clip.SampleAnimation(model,0);var bounds=BoundsOf(skin,squid.transform);model.transform.localScale*=22/bounds.size.z;bounds=BoundsOf(skin,squid.transform);model.transform.localPosition+=new Vector3(-bounds.center.x,-bounds.center.y,7-bounds.max.z);skin.sharedMaterials=new[]{bodyMat,finMat};skin.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;skin.receiveShadows=false;
   Bounds envelope=default;bool firstPoint=true;float padding=0;for(int i=0;i<12;i++){animation.clip.SampleAnimation(model,animation.clip.length*i/12);var points=Points(skin,squid.transform);foreach(var p in points){padding=Mathf.Max(padding,SquidSwimmer.RequiredPadding(p));var local=skin.rootBone.InverseTransformPoint(squid.transform.TransformPoint(p));if(firstPoint){envelope=new Bounds(local,Vector3.zero);firstPoint=false;}else envelope.Encapsulate(local);}}envelope.Expand(.003f);skin.localBounds=envelope;animation.clip.SampleAnimation(model,0);squid.clearancePadding=padding+.15f;var original=squid.GetComponent<MeshRenderer>();if(original)UnityEngine.Object.DestroyImmediate(original);var oldMesh=squid.GetComponent<MeshFilter>();if(oldMesh)UnityEngine.Object.DestroyImmediate(oldMesh);var motion=model.AddComponent<ReefImportedAnimation>();motion.speed=1;foreach(var proxy in squid.GetComponentsInChildren<CapsuleCollider>())if(proxy.gameObject.layer==9){proxy.radius=Mathf.Max(proxy.radius,2+squid.clearancePadding);proxy.height=24;proxy.center=new Vector3(0,0,-4);}squid.PlaceAboveSeabed();Debug.Log("SQUID_PLACED "+squid.name+" bounds="+BoundsOf(skin,squid.transform)+" clearancePadding="+squid.clearancePadding+" visibilityBounds="+skin.bounds);}
  var visual=UnityEngine.Object.FindFirstObjectByType<SquidSwimmer>().transform.Find("Approved Blender squid");PrefabUtility.SaveAsPrefabAsset(visual.gameObject,Folder+"/GiantSquid.prefab");Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();
 }
 public static void Validate(){EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var squids=UnityEngine.Object.FindObjectsByType<SquidSwimmer>(FindObjectsSortMode.None);if(squids.Length!=2)throw new Exception("Expected two independent squid encounters");Mesh shared=null;foreach(var squid in squids){var model=squid.transform.Find("Approved Blender squid");var animation=model.GetComponent<Animation>();var skin=model.GetComponentInChildren<SkinnedMeshRenderer>();if(shared&&shared!=skin.sharedMesh)throw new Exception("Squids no longer share their visual mesh");shared=skin.sharedMesh;if(skin.sharedMaterials.Length!=2||skin.bones.Length!=30||squid.GetComponent<MeshRenderer>()||squid.GetComponent<MeshFilter>())throw new Exception("Squid render setup failed");animation.clip.SampleAnimation(model.gameObject,0);var before=Points(skin,squid.transform);animation.clip.SampleAnimation(model.gameObject,animation.clip.length*.25f);var after=Points(skin,squid.transform);float deformation=0;for(int i=0;i<before.Length;i++)deformation=Mathf.Max(deformation,Vector3.Distance(before[i],after[i]));var bounds=BoundsOf(skin,squid.transform);if(deformation<.1f||bounds.size.z<20||bounds.size.z>24||skin.bounds.size.magnitude>40)throw new Exception("Invalid squid deformation, scale or culling bounds "+bounds+" rendered="+skin.bounds);var visible=skin.bounds;visible.Expand(.05f);foreach(var vertex in after)if(!visible.Contains(squid.transform.TransformPoint(vertex)))throw new Exception("Squid animation escaped visibility bounds");squid.Initialize();float travel=0;for(int i=0;i<5400;i++){var p=squid.transform.position;squid.Step(1f/30);travel+=Vector3.Distance(p,squid.transform.position);if(!squid.ClearPose(squid.transform.position,squid.transform.rotation))throw new Exception("Squid full-body reef penetration");}if(travel<15)throw new Exception("Squid motion stalled");Debug.Log("BLENDER_SQUID_VALIDATED "+squid.name+" travel180s="+travel+" deformation="+deformation+" fullBodyClear=true triangles="+skin.sharedMesh.triangles.Length/3);}
  ReefDaySix.Validate();
 }
 public static void Capture(){EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory("Renders/UnitySquid");var camera=Camera.main;camera.fieldOfView=55;foreach(var squid in UnityEngine.Object.FindObjectsByType<SquidSwimmer>(FindObjectsSortMode.None)){var model=squid.transform.Find("Approved Blender squid");model.GetComponent<Animation>().clip.SampleAnimation(model.gameObject,.5f);camera.transform.position=squid.transform.TransformPoint(new Vector3(15,5,8));camera.transform.LookAt(squid.transform.TransformPoint(new Vector3(0,0,-3)));UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>().Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/UnitySquid/"+(squid.name.StartsWith("Open")?"OpenWater":"Trench")+".png");}}
 public static void Inspect(){AssetDatabase.Refresh();var importer=(ModelImporter)AssetImporter.GetAtPath(Model);importer.animationType=ModelImporterAnimationType.Legacy;importer.importAnimation=true;importer.isReadable=true;importer.materialImportMode=ModelImporterMaterialImportMode.None;importer.animationCompression=ModelImporterAnimationCompression.Off;var clips=importer.defaultClipAnimations;foreach(var clip in clips){Debug.Log("SQUID_IMPORT_CLIP "+clip.name+" "+clip.firstFrame+".."+clip.lastFrame);clip.name="Swim";clip.loopTime=true;clip.wrapMode=WrapMode.Loop;}importer.clipAnimations=clips;importer.SaveAndReimport();var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Model));var skin=go.GetComponentInChildren<SkinnedMeshRenderer>();Debug.Log("SQUID_IMPORT mesh="+skin.sharedMesh.name+" bounds="+BoundsOf(skin,go.transform)+" bones="+skin.bones.Length+" rootScale="+go.transform.localScale);Debug.Log("SQUID_SPACE skinScale="+skin.transform.lossyScale+" boneScale="+skin.rootBone.lossyScale+" sourceBounds="+skin.sharedMesh.bounds+" rendererBounds="+skin.bounds+" localBounds="+skin.localBounds);foreach(var bone in skin.bones)if(bone.name=="Root"||bone.name=="Mantle")Debug.Log("SQUID_BONE "+bone.name+" position="+go.transform.InverseTransformPoint(bone.position));UnityEngine.Object.DestroyImmediate(go);}
}
}
